/**
 * DSKP catalogue types (FB-026, DSKP-T01; docs/architecture/v2-dskp-integration.md §2, ADR-0022).
 *
 * The catalogue is the official KSSM Tingkatan 4 and 5 curriculum standard (DSKP) of 13 subjects:
 * Subject -> Tingkatan -> Group (optional) -> Unit -> SK (Standard Kandungan) -> SP (Standard
 * Pembelajaran), with Tahap Penguasaan (TP 1-6) descriptors attached where the DSKP prints them.
 * M03 owns it (D12) and nothing writes it: the data files in `./data` are generated by
 * `scripts/fixtures/build-m03-dskp.ts` from `docs/reference/dskp/*.json`.
 *
 * Wire types (`Dskp*Data`, `TpDescriptor`, `TpTable`, ...) describe the committed JSON. Ids are
 * never stored: the runtime indexer (DSKP-T02) builds the composite keys of `./keys.ts`.
 *
 * This file is imported by the generator under `node --experimental-strip-types`, so it holds only
 * erasable TypeScript (no enums, no parameter properties) and no imports.
 */

export const DSKP_TINGKATAN = ['T4', 'T5'] as const
export type DskpTingkatan = (typeof DSKP_TINGKATAN)[number]

/** Subject codes. `MAT`, `SN`, `SEJ` keep the codes m28 Bijak SPM already uses. */
export const DSKP_SUBJECT_CODES = [
  'MAT',
  'MTM',
  'FIZ',
  'SN',
  'BM',
  'BI',
  'SEJ',
  'PI',
  'TI',
  'PM',
  'PSV',
  'LNS',
  'KPJ',
] as const
export type DskpSubjectCode = (typeof DSKP_SUBJECT_CODES)[number]

/** Where the DSKP prints the TP table of a subject. */
export type DskpTpLevel = 'unit' | 'sk'

export type DskpLanguage = 'ms' | 'en' | 'ms-Arab'
export type DskpSubjectKind = 'academic' | 'vocational'

/** Node fields whose text is Arabic-script (Jawi) and must be rendered right-to-left. */
export type DskpRtlField = 'sk' | 'sp' | 'tp'

/**
 * Closed set of review flags (section 2.3). A flag never blocks use, except `noStandard`: a
 * printed "No learning standard" slot is carried but is not selectable.
 */
export const DSKP_FLAGS = [
  'perluSemakanEjaan',
  'reconstructed',
  'inferred',
  'tpUnaligned',
  'noStandard',
  'draftEdition',
  'textDefect',
  'codeQuirk',
] as const
export type DskpFlag = (typeof DSKP_FLAGS)[number]

export type DskpKeyKind = 'g' | 'u' | 'sk' | 'sp'

/** Opaque composite keys, `SUBJECT:T4|T5:g|u|sk|sp:<printed code>` (see `keys.ts`). */
export type DskpGroupId = string & { readonly __dskpKind: 'g' }
export type DskpUnitId = string & { readonly __dskpKind: 'u' }
export type DskpSkId = string & { readonly __dskpKind: 'sk' }
export type DskpSpId = string & { readonly __dskpKind: 'sp' }

// -----------------------------------------------------------------------------------------------
// Wire shape of a subject file (`data/<slug>.json`)
// -----------------------------------------------------------------------------------------------

export type TpValue = 1 | 2 | 3 | 4 | 5 | 6

/**
 * One TP statement. `tp` is null only for the rows Landskap dan Nurseri prints unaligned (units
 * T4 1.0, 3.0, 4.0: one pooled row; T5 7.0: the row printed for "1-4", with `range: [1, 4]`).
 */
export interface TpDescriptor {
  tp: TpValue | null
  range?: [number, number]
  /** Bahasa Melayu only: Sangat Terhad ... Cemerlang. */
  label?: string
  text: string
}

/** A TP table. Katering Modul 1.0 has two (SK 1.1; SK 1.2 and 1.3); every other node has one. */
export interface TpTable {
  appliesToSk?: string[]
  rows: TpDescriptor[]
}

export interface DskpGroup {
  tingkatan: DskpTingkatan
  /** Pendidikan Moral only ("5.0"). */
  code?: string
  title: string
}

export interface DskpSp {
  /** As printed, including the Sejarah `K` prefix. */
  code: string
  text: string
  /** Sejarah: Elemen Kewarganegaraan dan Nilai Sivik item (code starts with K). */
  citizenship?: true
  flags?: DskpFlag[]
}

export interface DskpSk {
  code: string
  title: string
  flags?: DskpFlag[]
  /** Only for subjects with `tpLevel: 'sk'`. */
  tp?: TpTable[]
  sps: DskpSp[]
}

export interface DskpUnit {
  tingkatan: DskpTingkatan
  /** As printed: "1.0", "5.1", "1", "Tajuk 9". */
  code: string
  /** As printed in the extract (case kept). */
  title: string
  /** Index into the file's `groups`. */
  group?: number
  /** Matematik Tambahan elective package. */
  pkg?: string
  flags?: DskpFlag[]
  /** Only for subjects with `tpLevel: 'unit'`, and absent where the DSKP prints none. */
  tp?: TpTable[]
  sks: DskpSk[]
}

export interface DskpSubjectData {
  code: DskpSubjectCode
  groups: DskpGroup[]
  /** Tingkatan 4 first, then 5, each in print order (codes are never sorted). */
  units: DskpUnit[]
  /** The subject's general TP table (six rows), when the DSKP prints one. */
  generalTp: TpDescriptor[] | null
}

// -----------------------------------------------------------------------------------------------
// Eager index (`data/index.json`) and version (`data/version.json`)
// -----------------------------------------------------------------------------------------------

export interface DskpCounts {
  units: number
  sk: number
  /** Selectable SP (a `noStandard` slot is not counted). */
  sp: number
  /** Printed "No learning standard" slots (Bahasa Inggeris only). */
  slots: number
}

export interface DskpSubjectInfo {
  code: DskpSubjectCode
  /** Data file name, without extension. */
  slug: string
  name: string
  language: DskpLanguage
  kind: DskpSubjectKind
  groupNoun?: string
  unitNoun: string
  tpLevel: DskpTpLevel
  rtlFields: DskpRtlField[]
  /** M03's own subject code, or null (Landskap and Katering are not in M03's 31-subject list). */
  m03SubjectCode: string | null
  edition: Record<DskpTingkatan, string>
  counts: Record<DskpTingkatan, DskpCounts>
  /** Subject-wide flags (Pendidikan Islam: `perluSemakanEjaan`). */
  flags?: DskpFlag[]
  /** Tingkatan-wide flags (Bahasa Inggeris T4: `draftEdition`). */
  tingkatanFlags?: Partial<Record<DskpTingkatan, DskpFlag[]>>
}

export interface DskpVersionFile {
  version: string
  /** SHA-256 over the 13 subject files and the index (see the generator). */
  sha256: string
}
